def reference(inputs):
    def get(sub):
        for k, v in inputs.items():
            if sub in k:
                return v
        raise ValueError(sub)
    def mass(t):
        n = number(t)
        if n is None:
            raise ValueError('mass')
        s = t.lower()
        if 'kg' in s:
            return n * 1000.0
        if 'mg' in s:
            return n / 1000.0
        if 'lb' in s:
            return n * 453.59237
        return n
    def temp(t):
        n = number(t)
        if n is None:
            raise ValueError('temp')
        if '\u00b0f' in t.lower() or t.strip().lower().endswith('f'):
            return (n - 32) * 5.0 / 9.0 + 273.15
        if '\u00b0c' in t.lower() or t.strip().lower().endswith('c'):
            return n + 273.15
        return n
    def sh(t):
        n = number(t)
        if n is None:
            raise ValueError('sh')
        s = t.lower()
        if 'cal' in s and 'kcal' not in s:
            n = n * 4.184
        elif 'kcal' in s:
            n = n * 4184.0
        elif 'kj' in s:
            n = n * 1000.0
        if '/(kg' in s or '/kg' in s:
            n = n / 1000.0
        return n
    mw = mass(get('mass of the water'))
    tw = temp(get('initial temperature of the water'))
    ma = mass(get('mass of the aluminum'))
    ta = temp(get('initial temperature of the aluminum'))
    ca = sh(get('specific heat of aluminum'))
    cw = sh(get('specific heat of water'))
    Cw = mw * cw
    Ca = ma * ca
    T = (Cw * tw + Ca * ta) / (Cw + Ca)
    return {'equilibrium temperature in K': T}
